INSERT INTO gis_boundary_sources (jurisdiction_id,authority_name,source_title,source_url,source_type,provenance_status,retrieved_at,source_hash,notes) SELECT cj.id,'National Bureau of Statistics (NBS)','Administrative Map of Nigeria','https://www.nigerianstat.gov.ng/download/170','Official administrative reference','Referenced','2026-08-23 00:00:00+00','1b51fe18d3409c2324753a297b1746a80546f2eb2bf35ad32fc3f53e9fe8eb8c','Reference establishes Nigeria state administrative boundaries; not treated as cadastral geometry.' FROM continental_jurisdictions cj WHERE cj.country_code='NG' AND NOT EXISTS (SELECT 1 FROM gis_boundary_sources s WHERE s.jurisdiction_id=cj.id AND s.source_url='https://www.nigerianstat.gov.ng/download/170');
INSERT INTO gis_boundary_datasets (source_id,dataset_name,dataset_version,boundary_level,coordinate_reference_system,geometry_format,effective_from,geometry_status,validation_status,feature_count,notes) SELECT s.id,'Nigeria Administrative State Boundary Reference','NBS-ADMIN-MAP-2012','STATE','Not applicable - reference map','HTML/PDF reference',NULL,'Reference only','Pending',37,'NBS reference seeded for provenance and review. No polygon geometry is inferred from the map and it is not activated for point-in-polygon.' FROM gis_boundary_sources s WHERE s.source_url='https://www.nigerianstat.gov.ng/download/170' AND NOT EXISTS (SELECT 1 FROM gis_boundary_datasets d WHERE d.source_id=s.id AND d.dataset_version='NBS-ADMIN-MAP-2012');